function audit(){const old=inherited(()=>base.audit()),issues=[...(old.issues||[])];for(const r of records){const t=topics.find(x=>x.key===r.key);if(!t||t.label!==r.label||t.specificGuidance!==true||t.termResolution!==false||!r.refs.every(s=>sources[s.id]))issues.push('parallel-batch-121-123-selected:'+r.key);}return {...old,ok:!issues.length,issues,topics:topics.length};}
